<script nonce="<?= $nonce ?>">
var csrfToken = '<?= htmlspecialchars($sec->ct(), ENT_QUOTES, 'UTF-8') ?>';
(function(){var e=document.getElementById('tt');if(!e)return;var p=['texts','AI summaries','with tone detection'];var i=0,j=0,d=false,t=null;function f(){var c=p[i];if(d){e.textContent=c.substring(0,j-1);j--;if(j===0){d=false;i=(i+1)%p.length;clearTimeout(t);t=setTimeout(f,400);return;}clearTimeout(t);t=setTimeout(f,Math.random()*30+20);return;}if(j<c.length){e.textContent=c.substring(0,j+1);j++;clearTimeout(t);t=setTimeout(f,Math.random()*60+40);}else{clearTimeout(t);setTimeout(function(){d=true;clearTimeout(t);t=setTimeout(f,30);},2000);}}setTimeout(f,300);})();
document.addEventListener('DOMContentLoaded',function(){
var it=document.getElementById('it'),gb=document.getElementById('gb'),sp=document.getElementById('sp'),ra=document.getElementById('ra'),rtx=document.getElementById('rtx'),rst=document.getElementById('rst'),cb=document.getElementById('cb'),rb=document.getElementById('rb'),rr=document.getElementById('rr'),rv=document.getElementById('rv'),gen=document.getElementById('gen');
var fbw=document.getElementById('fbw'),fbt=document.getElementById('fbt'),fbbtn=document.getElementById('fbbtn');
var busy=false;
var lastInput='',lastOutput='';
rr.addEventListener('input',function(){rv.textContent=this.value+'%';});
function run(){
var text=it.value.trim();
if(text.length<5){alert('Please enter at least 5 characters.');return;}
if(busy)return;
busy=true;gb.disabled=true;sp.style.display='block';ra.classList.remove('show');
fbw.style.display='none';
var fd=new FormData();
fd.append('text',text);
fd.append('ratio',(parseInt(rr.value,10)/100).toString());
fd.append('generate',gen.checked?'1':'0');
fd.append('csrf_token',csrfToken);
fetch(window.location.pathname+'?_='+Date.now(),{method:'POST',body:fd,cache:'no-store'})
.then(function(r){if(!r.ok)throw new Error('Network error: '+r.status);return r.json();})
.then(function(d){
if(d.success){
lastInput=text;
lastOutput=d.summary;
rtx.textContent=d.summary;
var s=d.stats||{};
var items=[
{label:'Processing time',value:(s.processing_time||0).toFixed(3)+'s'},
{label:'Compression',value:(s.compression_ratio||0)+'%'},
{label:'Target',value:(s.target_compression||0)+'%'},
{label:'Sentences',value:(s.sentences_extracted||0)+' / '+(s.total_sentences||0)},
{label:'Language',value:(s.language||'en').toUpperCase()}
];
rst.innerHTML=items.map(function(x){return '<span>'+x.label+': <span class="sv">'+String(x.value)+'</span></span>';}).join('');
ra.classList.add('show');
fbw.style.display='block';
fbt.value='';
ra.scrollIntoView({behavior:'smooth',block:'center'});
}else{alert('Error: '+(d.error||'Processing failed'));}
})
.catch(function(e){alert('Server error: '+e.message);})
.finally(function(){busy=false;gb.disabled=false;sp.style.display='none';});
}
gb.addEventListener('click',run);
cb.addEventListener('click',function(){
var t=rtx.textContent;if(!t)return;
if(navigator.clipboard&&navigator.clipboard.writeText){
navigator.clipboard.writeText(t).then(function(){
cb.innerHTML=' Copied!';
cb.classList.add('cs');
setTimeout(function(){cb.innerHTML='<svg class="ic" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M8 5H6a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2v-1M8 5a2 2 0 002 2h2a2 2 0 002-2M8 5a2 2 0 012-2h2a2 2 0 012 2m0 0h2a2 2 0 012 2v3m2 4H10m0 0l3-3m-3 3l3 3"/></svg> Copy';cb.classList.remove('cs');},2000);
});
}
});
rb.addEventListener('click',function(){if(it.value.trim().length>=5)run();});
it.addEventListener('keydown',function(e){if((e.ctrlKey||e.metaKey)&&e.key==='Enter'){e.preventDefault();gb.click();}});
fbbtn.addEventListener('click',function(){
var fb=fbt.value.trim();
if(!lastOutput){alert('Please generate a summary first.');return;}
fbbtn.disabled=true;fbbtn.textContent='Sending...';
var fd=new FormData();
fd.append('action','feedback');
fd.append('csrf_token',csrfToken);
fd.append('fb_input',lastInput);
fd.append('fb_output',lastOutput);
fd.append('fb_text',fb);
fetch(window.location.pathname+'?_='+Date.now(),{method:'POST',body:fd,cache:'no-store'})
.then(function(r){return r.json();})
.then(function(d){
if(d.success){
fbbtn.textContent='✓ Submitted';
fbt.disabled=true;
setTimeout(function(){fbbtn.textContent='Submit feedback';fbbtn.disabled=false;fbt.disabled=false;fbt.value='';},2500);
}else{alert('Error: '+(d.error||'Failed to submit'));fbbtn.disabled=false;fbbtn.textContent='Submit feedback';}
})
.catch(function(e){alert('Network error: '+e.message);fbbtn.disabled=false;fbbtn.textContent='Submit feedback';});
});
});
</script>
</body>
</html>
